import{useEffect,useMemo,useState}from'react';import Icon from'./components/Icon';import QuickCapture from'./components/QuickCapture';import ActionMenu from'./components/ActionMenu';import TaskComposer from'./components/TaskComposer';import BackupTools from'./components/BackupTools';import ThemePicker from'./components/ThemePicker';import FocusTimer from'./components/FocusTimer';import AreaEditor from'./components/AreaEditor';import SkillEditor from'./components/SkillEditor';import TaskEditor from'./components/TaskEditor';import ResourceLibrary from'./components/ResourceLibrary';import AIReviewPanel from'./components/AIReviewPanel';import KnowledgeGraph from'./components/KnowledgeGraph';import CloudSync from'./components/CloudSync';import BookLearning from'./components/BookLearning';import GuidanceCenter,{GuideSettingsCard} from'./components/GuidanceCenter';import PersonMedia from'./components/PersonMedia';import RelationshipEngine from'./components/RelationshipEngine';import{useAppStore}from'./store/useAppStore';import{requestAIRecommendations}from'./services/aiRecommendations';import{seed}from'./domain/seed';import type{KnowledgeItem,LearningArea,Skill}from'./domain/types';
type Page='Dashboard'|'Today'|'Learning'|'Skills'|'Habits'|'Journal'|'Analytics'|'Search'|'People'|'Projects'|'Knowledge'|'Resources'|'Books'|'Graph'|'Settings';
const APP_VERSION='4.3.0';
const nav:[Page,string,keyof typeof import('lucide-react')][]=[['Dashboard','LayoutDashboard','LayoutDashboard'],['Today','Today','Sun'],['Learning','Growth','Compass'],['Skills','Growth','Sparkles'],['Habits','Growth','Repeat2'],['People','Connect','Users'],['Projects','Build','FolderKanban'],['Knowledge','Explore','BookOpen'],['Books','Explore','LibraryBig'],['Resources','Explore','Library'],['Graph','Explore','Share2'],['Journal','Reflect','NotebookPen'],['Analytics','Reflect','ChartNoAxesCombined']];
function App(){const{data,toggleTask,toggleHabit,updateLog}=useAppStore();const[page,setPage]=useState<Page>('Dashboard');const[query,setQuery]=useState('');const[dark,setDark]=useState(false);const[captureOpen,setCaptureOpen]=useState(false);const[theme,setTheme]=useState(()=>localStorage.getItem('personal-life-os-theme')||'lavender');useEffect(()=>{const handler=(event:any)=>setTheme(event.detail);window.addEventListener('life-os-theme',handler);return()=>window.removeEventListener('life-os-theme',handler)},[]);const themeColor=theme==='mint'?'#62a98b':theme==='sky'?'#5d91c5':theme==='peach'?'#d18b62':'#8b7cf6';const themeSoft=theme==='mint'?'#dff2e8':theme==='sky'?'#e3effa':theme==='peach'?'#fae9dd':'#e9e4f9';const completed=data.tasks.filter(t=>t.status==='done').length;const active=data.tasks.length-completed;const totalMinutes=data.tasks.filter(t=>t.status==='done').reduce((a,t)=>a+t.minutes,0)+data.log.minutes;const date=new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric'}).format(new Date());
const pageTitle=page==='Dashboard'?'Good morning, Jerry.':page==='Today'?'Today':page==='Learning'?'Learning Areas':page==='Skills'?'Skills':page==='Habits'?'Habits':page==='Resources'?'Resource Library':page==='Books'?'AI Book Learning':page==='Journal'?'Daily Journal':page;
return <div className={dark?'app dark':'app'} style={{'--accent':themeColor,'--accent-soft':themeSoft} as any}><aside className="sidebar"><div className="brand"><div className="brand-mark">✦</div><div><b>Personal Life OS</b><span>Grow · Learn · Connect</span></div></div><div className="workspace"><div className="avatar">J</div><span>Jerry’s workspace</span><Icon name="ChevronDown" size={14}/></div><nav>{nav.map(([label,group,icon])=><button key={label} className={page===label?'active':''} onClick={()=>setPage(label)}>{group==='Growth'&&label==='Learning'?<Icon name="Compass"/>:<Icon name={icon}/>}<span>{label}</span>{label==='Today'&&active>0&&<em>{active}</em>}</button>)}</nav><div className="nav-group"><small>SPACE</small><button onClick={()=>setPage('Search')}><Icon name="Search"/><span>Search</span><kbd>⌘ K</kbd></button><button onClick={()=>setPage('Settings')}><Icon name="Settings"/><span>Settings</span></button></div><div className="sidebar-bottom"><div className="streak-mini"><span>🔥</span><div><b>{Math.max(0,...data.habits.map(h=>h.streak))} day streak</b><small>Keep the rhythm going</small></div></div><button className="theme" onClick={()=>setDark(!dark)}><Icon name={dark?'Sun':'Moon'} size={16}/>{dark?'Light mode':'Dark mode'}</button></div></aside><main><header><div><div className="eyebrow">{date}</div><h1>{pageTitle}</h1></div><div className="header-actions"><button className="icon-button" onClick={()=>setDark(!dark)}><Icon name={dark?'Sun':'Moon'} size={18}/></button><button className="quick-add" onClick={()=>setCaptureOpen(true)}><Icon name="Plus" size={17}/> Quick capture</button><div className="avatar avatar-lg">J</div></div></header>{page==='Dashboard'&&<Dashboard data={data} completed={completed} totalMinutes={totalMinutes} setPage={setPage} toggleTask={toggleTask}/>} {page==='Today'&&<Today data={data} toggleTask={toggleTask} toggleHabit={toggleHabit} setPage={setPage}/>} {page==='Learning'&&<Areas areas={data.areas}/>} {page==='Skills'&&<Skills skills={data.skills} areas={data.areas}/>} {page==='Habits'&&<Habits data={data} toggleHabit={toggleHabit}/>} {page==='Journal'&&<Journal data={data} updateLog={updateLog}/>} {page==='Search'&&<Search data={data} query={query} setQuery={setQuery}/>} {page==='People'&&<PeoplePage/>} {page==='Resources'&&<ResourceLibrary areas={data.areas} skills={data.skills} projects={data.projects||[]}/>} {page==='Books'&&<BookLearning areas={data.areas} skills={data.skills} data={data} />} {page==='Graph'&&<KnowledgeGraph data={data}/>} {['Projects','Knowledge','Analytics','Settings'].includes(page)&&<ComingSoon page={page} setPage={setPage}/>}</main>{captureOpen&&<QuickCapture onClose={()=>setCaptureOpen(false)}/>}<GuidanceCenter/></div>}
function SectionTitle({title,link,onClick}:{title:string;link?:string;onClick?:()=>void}){return <div className="section-title"><h2>{title}</h2>{link&&<button onClick={onClick}>{link}<Icon name="ArrowUpRight" size={14}/></button>}</div>}
function Dashboard({data,completed,totalMinutes,setPage,toggleTask}:{data:any;completed:number;totalMinutes:number;setPage:(p:Page)=>void;toggleTask:(id:string)=>void}){const streak=Math.max(0,...data.habits.map((h:any)=>h.streak));const best=Math.max(0,...data.habits.map((h:any)=>h.best));const progress=Math.round(completed/data.tasks.length*100);return <div className="content"><div className="hero-grid"><div className="hero-card"><div className="hero-copy"><span className="pill purple">FOCUS FOR TODAY</span><h2>Small steps, meaningful<br/>momentum.</h2><p>Make space for the work that compounds.</p><button className="primary" onClick={()=>setPage('Today')}>Open today <Icon name="ArrowRight" size={16}/></button></div><div className="orb"><span>✦</span></div></div><div className="metric-card"><div className="metric-label"><span>Current streak</span><Icon name="Flame" size={17}/></div><strong>{streak} <small>days</small></strong><div className="muted">Best recorded <b>{best} days</b></div><div className="sparkline"><i/><i/><i/><i/><i/><i className="hot"/><i className="hot"/></div></div></div><div className="stat-row"><div><span>Today’s progress</span><b>{completed}<small> / {data.tasks.length} tasks</small></b><div className="progress"><i style={{width:`${progress}%`}}/></div></div><div><span>Learning time</span><b>{totalMinutes}<small> min today</small></b><div className="subtle">↑ 18% from last week</div></div><div><span>Active areas</span><b>{data.areas.length}</b><div className="subtle">Across 3 focus areas</div></div><div><span>Skills practiced</span><b>{data.skills.reduce((n:any,s:any)=>n+s.practiceCount,0)}</b><div className="subtle">Total sessions</div></div></div><div className="dashboard-grid"><section><SectionTitle title="Today’s tasks" link="View all" onClick={()=>setPage('Today')}/><div className="task-list">{data.tasks.slice(0,3).map((t:any)=><TaskRow key={t.id} task={t} toggle={()=>toggleTask(t.id)}/>)}</div><button className="add-line" onClick={()=>setPage('Today')}><Icon name="Plus" size={16}/> Add a task</button></section><section><SectionTitle title="Your focus areas" link="Manage" onClick={()=>setPage('Learning')}/><div className="area-list">{data.areas.map((a:LearningArea)=><div className="area-row" key={a.id}><span className="area-dot" style={{background:a.color}}/><div className="grow"><b>{a.name}</b><small>{a.focus}</small><div className="progress"><i style={{width:`${a.progress}%`,background:a.color}}/></div></div><strong>{a.progress}%</strong></div>)}</div></section></div><div className="dashboard-grid lower"><section><SectionTitle title="Recent activity" link="See journal" onClick={()=>setPage('Journal')}/><div className="activity-list">{data.activities.slice(0,3).map((a:any)=><div className="activity" key={a.id}><div className="activity-icon"><Icon name={a.type==='Task completed'?'CheckCircle2':a.type==='Skill practice'?'Code2':'BookOpen'} size={16}/></div><div><b>{a.label}</b><small>{a.meta}</small></div><time>{a.time}</time></div>)}</div></section><section className="knowledge-card"><div className="knowledge-top"><span className="pill teal">DAILY KNOWLEDGE</span><Icon name="ArrowUpRight" size={17}/></div><h3>What’s worth knowing today</h3><p>Daily Knowledge will surface 3–5 research signals from sources you trust.</p><div className="source-row"><span>⌁</span><span>PubMed · arXiv · Nature</span><button onClick={()=>setPage('Knowledge')}>Explore <Icon name="ArrowRight" size={14}/></button></div></section></div></div>}
function TaskRow({task,toggle}:{task:any;toggle:()=>void}){const{data,adjustTaskDifficulty,setData}=useAppStore();const[editing,setEditing]=useState<any>(null);const live=data.tasks.find(t=>t.id===task.id)||task;const remove=()=>{if(window.confirm('Delete this task?'))setData((d:any)=>({...d,tasks:d.tasks.filter((t:any)=>t.id!==live.id)}))};return <div className={'task-row '+(live.status==='done'?'done':'')}><button className="check" onClick={toggle}>{live.status==='done'&&<Icon name="Check" size={13}/>}</button><div className="task-body"><b>{live.title}</b><small>{live.description}</small></div><span className="tag">{live.minutes} min</span>{live.priority&&<span className="task-priority">{live.priority}</span>}<button className={'difficulty difficulty-'+live.difficulty.toLowerCase()} onClick={()=>adjustTaskDifficulty(live.id)}>{live.difficulty}</button><ActionMenu items={[{label:'Edit details',onClick:()=>setEditing(live)},{label:'Duplicate task',onClick:()=>setData((d:any)=>({...d,tasks:[{...live,id:'task-'+Date.now(),status:'todo',completedAt:undefined},...d.tasks]}))},{label:live.status==='done'?'Mark incomplete':'Mark complete',onClick:toggle},{label:'Delete task',danger:true,onClick:remove}]}/>{editing&&<TaskEditor task={editing} projects={data.projects||[]} onCancel={()=>setEditing(null)} onSave={(next:any)=>{setData((d:any)=>({...d,tasks:d.tasks.map((item:any)=>item.id===next.id?next:item)}));setEditing(null)}}/>}</div>}
function Today({data,toggleTask,toggleHabit,setPage}:{data:any;toggleTask:(id:string)=>void;toggleHabit:(id:string)=>void;setPage:(p:Page)=>void}){const{data:live,generateDailyTasks,autoTuneDifficulty,toggleTask:toggleLiveTask,toggleHabit:toggleLiveHabit}=useAppStore();const[people,setPeople]=useState<any[]>(()=>{try{return JSON.parse(localStorage.getItem('personal-life-os-people')||'[]')}catch{return[]}});const[captures]=useState<any[]>(()=>{try{return JSON.parse(localStorage.getItem('personal-life-os-captures')||'[]')}catch{return[]}});const logInteraction=(id:string)=>{const next=people.map(p=>p.id===id?{...p,lastInteraction:'Today',nextFollowUp:'In 2 weeks'}:p);setPeople(next);localStorage.setItem('personal-life-os-people',JSON.stringify(next))};return <div className="content"><div className="today-intro"><div><p className="muted">Daily focus · {live.tasks.length} tasks, {live.habits.length} habits</p><h2>Keep it light. Keep it moving.</h2></div><div className="today-actions"><TaskComposer/><button className="secondary" onClick={()=>generateDailyTasks()}><Icon name="Sparkles" size={16}/> Generate tasks</button><button className="secondary" onClick={autoTuneDifficulty}><Icon name="SlidersHorizontal" size={16}/> Tune difficulty</button><button className="secondary" onClick={()=>generateDailyTasks(true)}><Icon name="RefreshCw" size={16}/> Regenerate</button><button className="secondary" onClick={()=>setPage('Journal')}><Icon name="NotebookPen" size={16}/> Open daily log</button></div></div><FocusTimer/><div className="today-columns"><section><SectionTitle title="Daily progress"/><div className="task-list">{live.tasks.map((t:any)=><TaskRow key={t.id} task={t} toggle={()=>toggleLiveTask(t.id)}/>)}</div></section><section><SectionTitle title="Habits"/><div className="habit-list">{live.habits.map((h:any)=><div className="habit-row" key={h.id}><button className={'check '+(h.checked?'checked':'')} onClick={()=>toggleLiveHabit(h.id)}>{h.checked&&<Icon name="Check" size={13}/>}</button><div><b>{h.name}</b><small>{h.frequency} · {h.target}</small></div><span>🔥 {h.streak}</span></div>)}</div><div className="quote"><Icon name="Quote" size={18}/><p>Consistency is a form of self-trust.</p></div></section></div>{people.length>0&&<section className="relationship-followups"><SectionTitle title="Relationship follow-ups" link="Open People" onClick={()=>setPage('People')}/><div className="followup-list">{people.slice(0,3).map(p=><div className="followup-row" key={p.id}><div className="avatar person-avatar">{p.name.slice(0,1)}</div><div className="grow"><b>{p.name}</b><small>{p.nextFollowUp} · {p.relationship}</small></div><button className="secondary" onClick={()=>logInteraction(p.id)}><Icon name="MessageCircle" size={14}/> Log interaction</button></div>)}</div></section>}{captures.length>0&&<section className="capture-history"><SectionTitle title="Recent captures" link="Open journal" onClick={()=>setPage('Journal')}/>{captures.slice(0,3).map(c=><div className="capture-row" key={c.id}><Icon name="Zap" size={15}/><div><b>{c.text}</b><small>{c.people?.length?'People: '+c.people.join(', '):'Quick capture'} · {new Date(c.createdAt).toLocaleDateString()}</small></div></div>)}</section>}<section className="timeline"><SectionTitle title="Today’s activity"/><div className="activity-list">{live.activities.map((a:any)=><div className="activity" key={a.id}><div className="activity-icon"><Icon name="CircleDot" size={15}/></div><div><b>{a.label}</b><small>{a.type} · {a.meta}</small></div><time>{a.time}</time></div>)}</div></section></div>}
function Areas({areas}:{areas:LearningArea[]}){const{data,addArea,deleteArea,setData}=useAppStore();const[open,setOpen]=useState(false);const[editing,setEditing]=useState<LearningArea|null>(null);const remove=(id:string,name:string)=>{if(window.confirm(`Delete “${name}”? This cannot be undone.`))deleteArea(id)};const saveArea=(area:LearningArea)=>{setData((d:any)=>({...d,areas:d.areas.map((item:any)=>item.id===area.id?area:item)}));setEditing(null)};return <div className="content"><div className="toolbar"><p className="muted">Long-term directions that compound over time.</p><button className="primary" onClick={()=>setOpen(true)}><Icon name="Plus" size={16}/> New learning area</button></div><div className="cards-grid">{data.areas.map(a=><div className="feature-card" key={a.id}><div className="card-head"><span className="area-dot" style={{background:a.color}}/><span className="pill">{a.priority} priority</span><ActionMenu items={[{label:'Edit details',onClick:()=>setEditing(a)},{label:a.status==='Active'?'Pause area':'Resume area',onClick:()=>setData((d:any)=>({...d,areas:d.areas.map((x:any)=>x.id===a.id?{...x,status:x.status==='Active'?'Paused':'Active'}:x)}))},{label:'Delete area',danger:true,onClick:()=>remove(a.id,a.name)}]}/></div><h3>{a.name}</h3><p>{a.description}</p>{a.longTermGoal&&<div className="focus-line"><span>Long-term goal</span><b>{a.longTermGoal}</b></div>}<div className="focus-line"><span>Current focus</span><b>{a.focus}</b></div><div className="progress-line"><div className="progress"><i style={{width:`${a.progress}%`,background:a.color}}/></div><strong>{a.progress}%</strong></div><div className="chips">{a.topics.map(t=><span key={t}>{t}</span>)}</div>{a.resources?.length&&<small className="area-resources">{a.resources.length} resources saved</small>}</div>)}</div>{open&&<CreateForm kind="area" onCancel={()=>setOpen(false)} onSubmit={(name)=>{addArea(name);setOpen(false)}}/>}{editing&&<AreaEditor area={editing} onCancel={()=>setEditing(null)} onSave={saveArea}/>}</div>}
function Skills({skills,areas}:{skills:Skill[];areas:LearningArea[]}){const{data,addSkill,deleteSkill,practiceSkill,setData}=useAppStore();const[open,setOpen]=useState(false);const[editing,setEditing]=useState<Skill|null>(null);const remove=(id:string,name:string)=>{if(window.confirm(`Delete “${name}”? This cannot be undone.`))deleteSkill(id)};return <div className="content"><div className="toolbar"><p className="muted">Practice deliberately. Track the evidence.</p><button className="primary" onClick={()=>setOpen(true)}><Icon name="Plus" size={16}/> Add skill</button></div><div className="skill-table"><div className="table-head"><span>Skill</span><span>Level</span><span>Progress</span><span>Practice</span><span>Last active</span><span>Actions</span></div>{data.skills.map(s=><div className="skill-row" key={s.id}><div className="skill-name"><div className="skill-icon">{s.name[0]}</div><div><b>{s.name}</b><small>{s.focus}</small></div></div><span className="level">{s.level} <span>→ {s.target}</span></span><div className="skill-progress"><div className="progress"><i style={{width:`${s.progress}%`}}/></div><b>{s.progress}%</b></div><span>{s.practiceCount} sessions <small>· {s.minutes}m</small></span><span className="muted">{s.lastPracticed}</span><div className="skill-actions"><button onClick={()=>practiceSkill(s.id,20)}>+20m</button><ActionMenu items={[{label:'Record 20 min practice',onClick:()=>practiceSkill(s.id,20)},{label:'Edit details',onClick:()=>setEditing(s)},{label:'Delete skill',danger:true,onClick:()=>remove(s.id,s.name)}]}/></div></div>)}</div><div className="callout"><Icon name="Sparkles" size={19}/><div><b>Make the next practice obvious</b><p>Use +20m after a practice session to keep your skill history current.</p></div></div>{open&&<CreateForm kind="skill" onCancel={()=>setOpen(false)} onSubmit={(name)=>{addSkill(name);setOpen(false)}}/>}{editing&&<SkillEditor skill={editing} onCancel={()=>setEditing(null)} onSave={(skill)=>{setData((d:any)=>({...d,skills:d.skills.map((item:any)=>item.id===skill.id?skill:item)}));setEditing(null)}}/>}</div>}
function Habits({data,toggleHabit}:{data:any;toggleHabit:(id:string)=>void}){const{setData}=useAppStore();const[open,setOpen]=useState(false);const[name,setName]=useState('');const[frequency,setFrequency]=useState('Daily');const[target,setTarget]=useState('20 min');const add=()=>{if(!name.trim())return;setData((d:any)=>({...d,habits:[...d.habits,{id:'habit-'+Date.now(),name:name.trim(),frequency,target,streak:0,best:0,checked:false}]}));setName('');setOpen(false)};const remove=(id:string)=>{if(window.confirm('Delete this habit?'))setData((d:any)=>({...d,habits:d.habits.filter((h:any)=>h.id!==id)}))};return <div className="content"><div className="toolbar"><p className="muted">Small repeatable actions that protect your long-term goals.</p><button className="primary" onClick={()=>setOpen(true)}><Icon name="Plus" size={16}/> New habit</button></div><div className="habit-cards">{data.habits.map((h:any)=><div className="habit-card" key={h.id}><div className="habit-card-top"><button className={'check '+(h.checked?'checked':'')} onClick={()=>toggleHabit(h.id)}>{h.checked&&<Icon name="Check" size={13}/>}</button><ActionMenu items={[{label:'Edit habit',onClick:()=>{const name=window.prompt('Habit name',h.name);if(name)setData((d:any)=>({...d,habits:d.habits.map((x:any)=>x.id===h.id?{...x,name}:x)}))}},{label:h.checked?'Uncheck today':'Mark complete',onClick:()=>toggleHabit(h.id)},{label:'Delete habit',danger:true,onClick:()=>remove(h.id)}]}/></div><h3>{h.name}</h3><p>{h.frequency} · {h.target}</p><div className="habit-stats"><div><b>🔥 {h.streak}</b><small>current streak</small></div><div><b>{h.best}</b><small>best streak</small></div></div></div>)}</div>{open&&<div className="modal-backdrop" onMouseDown={()=>setOpen(false)}><form className="create-modal" onSubmit={e=>{e.preventDefault();add()}} onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><span className="pill purple">NEW HABIT</span><h2>What do you want to repeat?</h2></div><button type="button" className="modal-close" onClick={()=>setOpen(false)}>×</button></div><label>Name<input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Read 10 pages"/></label><label>Frequency<select value={frequency} onChange={e=>setFrequency(e.target.value)}><option>Daily</option><option>Weekdays</option><option>Weekly</option></select></label><label>Target<input value={target} onChange={e=>setTarget(e.target.value)} placeholder="e.g. 20 min"/></label><div className="modal-actions"><button type="button" className="secondary" onClick={()=>setOpen(false)}>Cancel</button><button className="primary" disabled={!name.trim()}>Create habit</button></div></form></div>}</div>}
function Journal({data,updateLog}:{data:any;updateLog:(f:any,v:any)=>void}){const[history,setHistory]=useState<any[]>(()=>{try{return JSON.parse(localStorage.getItem('personal-life-os-journal-history')||'[]')}catch{return[]}});const[message,setMessage]=useState('');const[query,setQuery]=useState('');const[selected,setSelected]=useState<any>(null);const completed=data.tasks.filter((t:any)=>t.status==='done').map((t:any)=>t.title);const save=()=>{const snapshot={id:Date.now().toString(),date:data.log.date||new Date().toISOString().slice(0,10),log:data.log,tasks:completed};const next=[snapshot,...history.filter(item=>item.date!==snapshot.date)].slice(0,90);setHistory(next);localStorage.setItem('personal-life-os-journal-history',JSON.stringify(next));setMessage('Saved to journal history');setTimeout(()=>setMessage(''),1800)};const filtered=history.filter(item=>(item.date+' '+(item.log?.learned||'')+' '+(item.log?.progress||'')).toLowerCase().includes(query.toLowerCase()));return <div className="content narrow"><div className="journal-header"><div><span className="pill purple">DAILY LOG</span><h2>What moved today?</h2><p className="muted">Your completed tasks and activities appear here automatically.</p></div><div className="log-time"><b>{data.log.minutes}</b><small>minutes learning</small></div></div><div className="auto-log"><Icon name="Sparkles" size={17}/><div><b>Automatically captured</b><p>{completed.join(' · ')||'Complete a task to see it here.'}</p></div></div><div className="journal-form">{[['learned','What did you learn?','A concept, connection, or question that stayed with you.'],['progress','Biggest progress today','What feels a little easier or clearer now?'],['problems','What got in the way?','Be honest — this helps plan tomorrow.'],['tomorrow','Tomorrow I want to…','One small next step is enough.'],['notes','Free notes','Anything else worth remembering.']].map(([f,l,p])=><label key={f}>{l}<textarea value={data.log[f]} onChange={e=>updateLog(f,e.target.value)} placeholder={p}/></label>)}</div><div className="journal-actions"><button className="primary" onClick={save}><Icon name="Save" size={16}/> Save today's log</button>{message&&<span className="muted">{message}</span>}</div><section className="journal-history"><SectionTitle title="Journal history"/><div className="journal-search"><Icon name="Search" size={15}/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search dates and reflections…"/></div>{filtered.length?<div className="journal-history-layout"><div>{filtered.slice(0,12).map(item=><button className={'journal-history-item '+(selected?.id===item.id?'selected':'')} key={item.id} onClick={()=>setSelected(item)}><div><b>{item.date}</b><small>{item.tasks?.length?item.tasks.length+' completed tasks':'No completed tasks'} · {item.log?.minutes||0} minutes</small></div><p>{item.log?.progress||item.log?.learned||'No reflection saved.'}</p></button>)}</div>{selected&&<article className="journal-detail"><span className="pill purple">{selected.date}</span><h3>Daily reflection</h3><div><b>Learned</b><p>{selected.log?.learned||'—'}</p></div><div><b>Progress</b><p>{selected.log?.progress||'—'}</p></div><div><b>Problems</b><p>{selected.log?.problems||'—'}</p></div><div><b>Tomorrow</b><p>{selected.log?.tomorrow||'—'}</p></div><div><b>Completed tasks</b><p>{selected.tasks?.join(' · ')||'—'}</p></div></article>}</div>:<p className="muted">Saved journal entries will appear here.</p>}</section></div>}
function Search({data,query,setQuery}:{data:any;query:string;setQuery:(q:string)=>void}){const results=useMemo(()=>{const captures=JSON.parse(localStorage.getItem('personal-life-os-captures')||'[]').map((x:any)=>({...x,name:x.text,type:'Quick capture'}));const people=JSON.parse(localStorage.getItem('personal-life-os-people')||'[]').map((x:any)=>({...x,name:x.name,type:'Person'}));const knowledge=JSON.parse(localStorage.getItem('personal-life-os-knowledge')||'[]').map((x:any)=>({...x,name:x.title,type:'Knowledge'}));return [...data.areas.map((x:any)=>({...x,type:'Learning area'})),...data.skills.map((x:any)=>({...x,type:'Skill'})),...data.tasks.map((x:any)=>({...x,name:x.title,type:'Task'})),...people,...knowledge,...captures].filter((x:any)=>(x.name||'').toLowerCase().includes(query.toLowerCase()))},[data,query]);return <div className="content narrow"><div className="search-box"><Icon name="Search"/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search across your Life OS…"/><kbd>ESC</kbd></div><p className="muted search-hint">{query?String(results.length)+' results':'Try “Alex”, “Python”, “BCI”, or “Bayesian”'}</p>{query&&results.map((r:any)=><div className="result" key={r.id}><div className="skill-icon">{(r.name||'?')[0]}</div><div><b>{r.name}</b><small>{r.type}</small></div><Icon name="ArrowUpRight" size={16}/></div>)}</div>}
async function fetchLiveKnowledge():Promise<KnowledgeItem[]>{const q='(neuroscience OR brain-computer interface OR machine learning)';const [pmc,cr]=await Promise.all([fetch(`https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=${encodeURIComponent(q)}&format=json&pageSize=5&sort_date=y`).then(r=>r.json()),fetch(`https://api.crossref.org/works?query=${encodeURIComponent(q)}&filter=from-pub-date:2025-01-01&sort=published&order=desc&rows=5&select=title,DOI,published,container-title,URL,abstract`).then(r=>r.json())]);const pub=(pmc.resultList?.result||[]).map((x:any):KnowledgeItem=>({id:`pmc-${x.id}`,title:x.title||'Untitled publication',source:'Europe PMC',publishedAt:x.firstPublicationDate||x.pubYear||'Recent',field:x.title?.toLowerCase().includes('brain')?'Neuroscience':'AI / Machine Learning',summary:(x.abstractText||'Publication record available through Europe PMC.').replace(/<[^>]+>/g,''),whyItMatters:'A current research signal connected to your learning areas.',url:x.fullTextUrlList?.fullTextUrl?.[0]?.url||`https://europepmc.org/article/${x.source}/${x.id}`}));const cross=(cr.message?.items||[]).map((x:any,i:number):KnowledgeItem=>{const date=x.published?.['date-parts']?.[0]?.join('-')||'Recent';return{id:`crossref-${x.DOI||i}`,title:x.title?.[0]||'Untitled work',source:x['container-title']?.[0]||'Crossref',publishedAt:date,field:'AI / Machine Learning',summary:(x.abstract||'Research metadata available through Crossref.').replace(/<[^>]+>/g,''),whyItMatters:'A newly indexed research work that may inform your next project or study session.',url:x.URL||`https://doi.org/${x.DOI}`}});const seen=new Set<string>();return[...pub,...cross].filter(x=>{const key=(x.url+x.title).toLowerCase();if(seen.has(key))return false;seen.add(key);return true}).slice(0,5)}
function KnowledgePage({items}:{items:KnowledgeItem[]}){const[current,setCurrent]=useState(items);const[field,setField]=useState('All');const[view,setView]=useState('all');const[savedIds,setSavedIds]=useState<string[]>(()=>JSON.parse(localStorage.getItem('personal-life-os-saved-knowledge')||'[]'));const[readIds,setReadIds]=useState<string[]>(()=>JSON.parse(localStorage.getItem('personal-life-os-read-knowledge')||'[]'));const[hiddenIds,setHiddenIds]=useState<string[]>(()=>JSON.parse(localStorage.getItem('personal-life-os-hidden-knowledge')||'[]'));const[ratings,setRatings]=useState<Record<string,number>>(()=>JSON.parse(localStorage.getItem('personal-life-os-knowledge-ratings')||'{}'));const[loading,setLoading]=useState(false);const[message,setMessage]=useState('Showing your saved reading queue.');const fields=['All',...Array.from(new Set(current.map(i=>i.field)))];const visible=(field==='All'?current:current.filter(i=>i.field===field)).filter(i=>(view==='all'||savedIds.includes(i.id))&&!hiddenIds.includes(i.id));useEffect(()=>{const saved=localStorage.getItem('personal-life-os-knowledge');if(saved)try{setCurrent(JSON.parse(saved))}catch{}},[]);const toggle=(id:string,type:'saved'|'read')=>{const setter=type==='saved'?setSavedIds:setReadIds;const key=type==='saved'?'personal-life-os-saved-knowledge':'personal-life-os-read-knowledge';setter(previous=>{const next=previous.includes(id)?previous.filter(item=>item!==id):[...previous,id];localStorage.setItem(key,JSON.stringify(next));return next})};const rate=(id:string,value:number)=>{const next={...ratings,[id]:value};setRatings(next);localStorage.setItem('personal-life-os-knowledge-ratings',JSON.stringify(next))};const refresh=async()=>{setLoading(true);setMessage('Searching Europe PMC and Crossref…');try{const next=await fetchLiveKnowledge();setCurrent(next);localStorage.setItem('personal-life-os-knowledge',JSON.stringify(next));setMessage('Updated just now · '+next.length+' items')}catch{setMessage('Unable to refresh right now. Showing the saved reading queue.')}finally{setLoading(false)}};return <div className="content"><div className="knowledge-header"><div><span className="pill teal">DAILY KNOWLEDGE</span><h2>Signals worth your attention.</h2><p className="muted">{message}</p></div><button className="primary" onClick={refresh} disabled={loading}><Icon name="RefreshCw" size={16}/> {loading?'Refreshing…':'Refresh knowledge'}</button></div><div className="knowledge-filters">{fields.map(f=><button key={f} className={field===f?'active':''} onClick={()=>{setField(f);setView('all')}}>{f}</button>)}<button className={view==='saved'?'active':''} onClick={()=>setView(view==='saved'?'all':'saved')}><Icon name="Bookmark" size={14}/> Saved only</button><button className={view==='rated'?'active':''} onClick={()=>setView(view==='rated'?'all':'rated')}><Icon name="Star" size={14}/> Rated</button></div><div className="knowledge-feed">{visible.filter(item=>view!=='rated'||ratings[item.id]).map(item=>{const isSaved=savedIds.includes(item.id);const isRead=readIds.includes(item.id);const rating=ratings[item.id]||0;return <article className={'knowledge-item '+(isRead?'knowledge-read':'')} key={item.id}><div className="knowledge-item-top"><span className="source-badge">{item.source}</span><span>{item.publishedAt}</span></div><h3>{item.title}</h3><span className="knowledge-field">{item.field}</span>{item.tags?.length&&<div className="knowledge-tags">{item.tags.map(tag=><span key={tag}>#{tag}</span>)}</div>}<p>{item.summary}</p><div className="why"><b>Why it matters</b><span>{item.whyItMatters}</span></div><div className="knowledge-rating"><small>Your rating</small>{[1,2,3,4,5].map(value=><button key={value} className={rating>=value?'active':''} onClick={()=>rate(item.id,value)}>★</button>)}</div><div className="knowledge-actions"><a href={item.url} target="_blank" rel="noreferrer" onClick={()=>toggle(item.id,'read')}>Open original source <Icon name="ArrowUpRight" size={14}/></a><button className={isSaved?'saved':''} onClick={()=>toggle(item.id,'saved')}><Icon name="Bookmark" size={14}/>{isSaved?'Saved':'Save'}</button><button className={isRead?'saved':''} onClick={()=>toggle(item.id,'read')}><Icon name="Check" size={14}/>{isRead?'Read':'Mark read'}</button><button onClick={()=>{const next=[...hiddenIds,item.id];setHiddenIds(next);localStorage.setItem('personal-life-os-hidden-knowledge',JSON.stringify(next))}}>Not interested</button></div></article>})}</div>{(view==='saved'||view==='rated')&&!visible.length&&<div className="empty-page"><h2>No items yet</h2><p>Save or rate a research signal to build your personal library.</p></div>}<div className="knowledge-note"><Icon name="Info" size={17}/><span>Saved, read, hidden and rating states stay on this device. Refresh searches Europe PMC and Crossref.</span></div></div>}
function PeoplePage(){type Person={id:string;name:string;relationship:string;organisation:string;location:string;interests:string[];notes:string;lastInteraction:string;nextFollowUp:string;cadence:string;avatar?:string;images?:string[];interactions?:Array<{date:string;note:string}>};const defaults:Person[]=[{id:'person-1',name:'Alex Chen',relationship:'Friend · Research collaborator',organisation:'Independent',location:'New York',interests:['BCI','R','Photography'],notes:'Learning R and interested in reading BCI papers together.',lastInteraction:'Today',nextFollowUp:'Next week',cadence:'Every 2 weeks'},{id:'person-2',name:'Maya Patel',relationship:'Mentor',organisation:'NeuroTech Lab',location:'Boston',interests:['Neuroscience','Scientific writing'],notes:'Ask about the latest motor imagery papers.',lastInteraction:'12 days ago',nextFollowUp:'In 2 days',cadence:'Monthly'}];const[people,setPeople]=useState<Person[]>(()=>{try{return JSON.parse(localStorage.getItem('personal-life-os-people')||'null')||defaults}catch{return defaults}});const[open,setOpen]=useState(false);const[name,setName]=useState('');const[relationship,setRelationship]=useState('Friend');const[search,setSearch]=useState('');const log=(person:Person,note:string='Interaction recorded')=>save(people.map(p=>p.id===person.id?{...p,lastInteraction:'Today',nextFollowUp:'In 2 weeks',interactions:[{date:'Today',note},...(p.interactions||[])].slice(0,20)}:p));const save=(next:Person[])=>{setPeople(next);localStorage.setItem('personal-life-os-people',JSON.stringify(next))};const add=()=>{if(!name.trim())return;save([{id:Date.now().toString(),name:name.trim(),relationship,organisation:'',location:'',interests:[],notes:'',lastInteraction:'Not yet',nextFollowUp:'Set a follow-up',cadence:'Monthly',interactions:[]},...people]);setName('');setOpen(false)};const visible=people.filter(p=>(p.name+' '+p.relationship+' '+p.interests.join(' ')).toLowerCase().includes(search.toLowerCase()));return <div className="content"><div className="people-header"><div><span className="pill purple">PEOPLE</span><h2>Keep the people who matter in view.</h2><p className="muted">A lightweight relationship memory, connected to your learning and life.</p></div><button className="primary" onClick={()=>setOpen(true)}><Icon name="Plus" size={16}/> Add person</button></div><div className="people-toolbar"><div className="search-field"><Icon name="Search" size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search people, interests, notes…"/></div><span className="muted">{people.length} people · {people.filter(p=>p.nextFollowUp!=='Set a follow-up').length} follow-ups tracked</span></div><RelationshipEngine people={people}/><div className="people-grid">{visible.map(person=><article className="person-card" key={person.id}><div className="person-card-head"><PersonMedia name={person.name} avatar={person.avatar} images={person.images} onChange={(avatar,images)=>save(people.map(p=>p.id===person.id?{...p,avatar,images}:p))}/><ActionMenu items={[{label:'Edit name',onClick:()=>{const name=window.prompt('Person name',person.name);if(name)save(people.map(p=>p.id===person.id?{...p,name}:p))}},{label:'Edit notes',onClick:()=>{const notes=window.prompt('Notes',person.notes);if(notes!==null)save(people.map(p=>p.id===person.id?{...p,notes}:p))}},{label:'Edit interests',onClick:()=>{const value=window.prompt('Interests (comma separated)',person.interests.join(', '));if(value!==null)save(people.map(p=>p.id===person.id?{...p,interests:value.split(',').map(x=>x.trim()).filter(Boolean)}:p))}},{label:'Schedule follow-up',onClick:()=>save(people.map(p=>p.id===person.id?{...p,nextFollowUp:'Next week'}:p))},{label:'Log interaction',onClick:()=>log(person)},{label:'Delete person',danger:true,onClick:()=>{if(window.confirm('Remove this person?'))save(people.filter(p=>p.id!==person.id))}}]}/></div><h3>{person.name}</h3><span className="person-relation">{person.relationship}</span>{(person.organisation||person.location)&&<p className="person-meta">{[person.organisation,person.location].filter(Boolean).join(' · ')}</p>}<div className="person-section"><small>INTERESTS</small><div className="chips">{person.interests.map(tag=><span key={tag}>{tag}</span>)}{!person.interests.length&&<span className="muted">Add interests later</span>}</div></div><p className="person-notes">{person.notes||'No notes yet. Capture what you want to remember.'}</p><div className="person-followup"><div><small>LAST INTERACTION</small><b>{person.lastInteraction}</b></div><div><small>NEXT FOLLOW-UP</small><b>{person.nextFollowUp}</b></div></div><button className="secondary person-log" onClick={()=>log(person)}><Icon name="MessageCircle" size={15}/> Log interaction</button><details className="person-timeline"><summary>View timeline · {(person.interactions||[]).length}</summary>{(person.interactions||[]).map((entry,index)=><div key={index}><b>{entry.date}</b><span>{entry.note}</span></div>)}{!(person.interactions||[]).length&&<span className="muted">No interactions recorded yet.</span>}</details></article>)}</div>{open&&<div className="modal-backdrop" onMouseDown={()=>setOpen(false)}><form className="create-modal" onSubmit={e=>{e.preventDefault();add()}} onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><span className="pill purple">NEW PERSON</span><h2>Who do you want to remember?</h2></div><button type="button" className="modal-close" onClick={()=>setOpen(false)}>×</button></div><label>Name<input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Alex Chen"/></label><label>Relationship<select value={relationship} onChange={e=>setRelationship(e.target.value)}><option>Friend</option><option>Mentor</option><option>Colleague</option><option>Family</option><option>Research collaborator</option></select></label><p className="muted">You can add interests, notes and follow-up details after creating them.</p><div className="modal-actions"><button type="button" className="secondary" onClick={()=>setOpen(false)}>Cancel</button><button className="primary" disabled={!name.trim()}>Create person</button></div></form></div>}</div>}function ComingSoon({page,setPage}:{page:Page;setPage:(p:Page)=>void}){if(page==='Knowledge')return <KnowledgePage items={seed.knowledge}/>;if(page==='Projects')return <ProjectsPage/>;if(page==='Analytics')return <AnalyticsPage/>;if(page==='Settings')return <SettingsPage/>;return <div className="content empty-page"><div className="empty-icon"><Icon name={page==='People'?'Users':'Settings'} size={30}/></div><h2>{page} is next</h2><p>This space is reserved for the next phase of Personal Life OS. Your Phase 1 foundation is ready: linked activities, local-first data and a calm daily workflow.</p><button className="primary" onClick={()=>setPage('Dashboard')}>Back to dashboard</button></div>}
function ProjectsPage(){const{data,addProject,addGoal,deleteProject,deleteGoal,setData}=useAppStore();const projects=data.projects||seed.projects;const goals=data.goals||seed.goals;const[form,setForm]=useState<'project'|'goal'|null>(null);return <div className="content"><div className="toolbar"><p className="muted">Projects turn long-term direction into visible progress.</p><button className="primary" onClick={()=>setForm('project')}><Icon name="Plus" size={16}/> New project</button></div><div className="project-goal-layout"><section><SectionTitle title="Active projects"/><div className="project-list">{projects.map(p=><div className="project-card" key={p.id}><div className="project-card-head"><span className="area-dot" style={{background:p.color}}/><span className="pill">{p.type}</span><span className="project-status">{p.status}</span><ActionMenu items={[{label:'Edit project',onClick:()=>{const name=window.prompt('Project name',p.name);const next=window.prompt('Next step',p.next);if(name)setData((d:any)=>({...d,projects:d.projects.map((x:any)=>x.id===p.id?{...x,name,next:next||x.next}:x)}))}},{label:'Add milestone',onClick:()=>{const milestone=window.prompt('Milestone');if(milestone)setData((d:any)=>({...d,projects:d.projects.map((x:any)=>x.id===p.id?{...x,milestones:[...(x.milestones||[]),milestone]}:x)}))}},{label:'Toggle complete',onClick:()=>setData((d:any)=>({...d,projects:d.projects.map((x:any)=>x.id===p.id?{...x,status:x.status==='Completed'?'In progress':'Completed'}:x)}))},{label:'Delete project',danger:true,onClick:()=>deleteProject(p.id)}]}/></div><h3>{p.name}</h3><p className="project-meta">{p.meta}</p>{p.milestones?.length&&<div className="milestone-list">{p.milestones.map((milestone,index)=><span key={index}><Icon name="CheckCircle2" size={12}/>{milestone}</span>)}</div>}<div className="project-progress"><div className="progress"><i style={{width:`${p.progress}%`,background:p.color}}/></div><b>{p.progress}%</b></div><div className="project-footer"><span><Icon name="CalendarDays" size={13}/> {p.deadline}</span><span><Icon name="ArrowRight" size={13}/> Next: {p.next}</span></div></div>)}</div></section><section><SectionTitle title="Goals"/><div className="goal-list">{goals.map(g=><div className="goal-row" key={g.id}><div className="goal-ring" style={{'--goal-progress':`${g.progress*3.6}deg`} as React.CSSProperties}><b>{g.progress}%</b></div><div><b>{g.title}</b><small>{g.period} · {g.detail}</small><div className="progress"><i style={{width:`${g.progress}%`}}/></div>{g.milestones?.length&&<div className="milestone-list">{g.milestones.map((milestone,index)=><span key={index}><Icon name="CheckCircle2" size={12}/>{milestone}</span>)}</div>}</div><ActionMenu items={[{label:'Edit goal',onClick:()=>{const title=window.prompt('Goal title',g.title);if(title)setData((d:any)=>({...d,goals:d.goals.map((x:any)=>x.id===g.id?{...x,title}:x)}))}},{label:'Increase progress',onClick:()=>setData((d:any)=>({...d,goals:d.goals.map((x:any)=>x.id===g.id?{...x,progress:Math.min(100,x.progress+10)}:x)}))},{label:'Add milestone',onClick:()=>{const milestone=window.prompt('Milestone');if(milestone)setData((d:any)=>({...d,goals:d.goals.map((x:any)=>x.id===g.id?{...x,milestones:[...(x.milestones||[]),milestone]}:x)}))}},{label:'Reset progress',onClick:()=>setData((d:any)=>({...d,goals:d.goals.map((x:any)=>x.id===g.id?{...x,progress:0}:x)}))},{label:'Delete goal',danger:true,onClick:()=>deleteGoal(g.id)}]}/></div>)}</div><button className="add-line" onClick={()=>setForm('goal')}><Icon name="Plus" size={16}/> Add a goal</button></section></div><div className="callout project-callout"><Icon name="Target" size={19}/><div><b>Make the next step concrete</b><p>Projects and goals are now backed by the same local data layer as your learning areas and skills.</p></div><button className="secondary" onClick={()=>setForm('project')}>Plan next step</button></div>{form&&<CreateForm kind={form} onCancel={()=>setForm(null)} onSubmit={(name)=>{form==='project'?addProject(name):addGoal(name);setForm(null)}}/>}</div>}
export default App;
function CreateForm({kind,onCancel,onSubmit}:{kind:'area'|'skill'|'project'|'goal';onCancel:()=>void;onSubmit:(name:string)=>void}){const[name,setName]=useState('');const isArea=kind==='area';const isSkill=kind==='skill';const isProject=kind==='project';const label=isArea?'learning area':isSkill?'skill':isProject?'project':'goal';return <div className="modal-backdrop" onMouseDown={onCancel}><form className="create-modal" onSubmit={e=>{e.preventDefault();if(name.trim())onSubmit(name.trim())}} onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><div><span className="pill purple">NEW {label.toUpperCase()}</span><h2>{isArea?'What direction are you growing?':isSkill?'What skill are you building?':isProject?'What project are you starting?':'What goal do you want to pursue?'}</h2></div><button type="button" className="modal-close" onClick={onCancel}>×</button></div><label>Name<input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder={isArea?'e.g. Psychology':isSkill?'e.g. MATLAB':isProject?'e.g. Build a literature review':'e.g. Finish 10 practice sessions'} /></label><p className="muted">You can add details, milestones and progress after creating it.</p><div className="modal-actions"><button type="button" className="secondary" onClick={onCancel}>Cancel</button><button className="primary" disabled={!name.trim()}>Create {label}</button></div></form></div>}
function AnalyticsPage(){const{data}=useAppStore();const[history]=useState<any[]>(()=>{try{return JSON.parse(localStorage.getItem('personal-life-os-journal-history')||'[]')}catch{return[]}});const today=new Date();const dates=Array.from({length:7},(_,index)=>{const date=new Date(today);date.setDate(today.getDate()-(6-index));return date.toISOString().slice(0,10)});const entries=dates.map(date=>history.find(item=>item.date===date)||{date,log:{minutes:date===data.log.date?data.log.minutes:0},tasks:date===data.log.date?data.tasks.filter((t:any)=>t.status==='done').map((t:any)=>t.title):[]});const minutes=entries.reduce((sum,item)=>sum+(item.log?.minutes||0),0);const done=entries.reduce((sum,item)=>sum+(item.tasks?.length||0),0);const total=Math.max(done,data.tasks.length);const maxMinutes=Math.max(...entries.map(item=>item.log?.minutes||0),1);const topArea=[...data.areas].sort((a,b)=>b.progress-a.progress)[0];const topSkill=[...data.skills].sort((a,b)=>b.minutes-a.minutes)[0];const practice=data.skills.reduce((sum,skill)=>sum+skill.practiceCount,0);return <div className="content"><div className="analytics-header"><div><span className="pill purple">PROGRESS REVIEW</span><h2>See what is compounding.</h2><p className="muted">Real activity from your tasks, skills and journal history.</p></div><span className="muted">Last 7 days</span></div><div className="analytics-stats"><div><span>Learning time</span><b>{minutes} min</b><small>last 7 days</small></div><div><span>Tasks completed</span><b>{done}</b><small>{Math.round(done/Math.max(total,1)*100)}% of current plan</small></div><div><span>Active areas</span><b>{data.areas.length}</b><small>long-term directions</small></div><div><span>Skill practice</span><b>{practice}</b><small>total sessions</small></div></div><div className="analytics-grid"><section className="analytics-card"><SectionTitle title="Learning time · last 7 days"/><div className="bar-chart">{entries.map((entry,index)=><div className="bar-col" key={entry.date}><div className="bar-track"><i style={{height:((entry.log?.minutes||0)/maxMinutes*100)+'%'}}/></div><small>{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][new Date(entry.date+'T12:00:00').getDay()]}</small><b>{entry.log?.minutes||0}</b></div>)}</div></section><section className="analytics-card"><SectionTitle title="Focus areas"/><div className="focus-analytics">{data.areas.map(a=><div key={a.id}><div><b>{a.name}</b><span>{a.progress}%</span></div><div className="progress"><i style={{width:a.progress+'%',background:a.color}}/></div></div>)}</div></section></div><section className="weekly-review"><div><span className="pill teal">WEEKLY REVIEW</span><h2>Your week in one glance.</h2><p>You've completed {done} tasks and tracked {minutes} minutes of learning in the last 7 days. Your strongest current direction is {topArea?.name||'still emerging'}, while {topSkill?.name||'your skills'} has the most practice history.</p></div><div className="review-list"><div><Icon name="CheckCircle2" size={16}/><span><b>Keep</b> your small daily progress tasks.</span></div><div><Icon name="Target" size={16}/><span><b>Focus</b> one next step in {topArea?.name||'your top area'}.</span></div><div><Icon name="Sparkles" size={16}/><span><b>Strengthen</b> a skill with a deliberate practice session.</span></div></div></section><AIRecommendationsPanel data={data}/><AIReviewPanel data={data}/></div>}
function SettingsPage(){const{data,setData}=useAppStore();const[key,setKey]=useState(()=>localStorage.getItem('personal-life-os-openai-key')||'');const[show,setShow]=useState(false);const[saved,setSaved]=useState(false);const save=()=>{localStorage.setItem('personal-life-os-openai-key',key.trim());setSaved(true);setTimeout(()=>setSaved(false),1800)};const clear=()=>{localStorage.removeItem('personal-life-os-openai-key');setKey('');setSaved(false)};return <div className="content narrow"><div className="settings-header"><span className="pill purple">SETTINGS</span><h2>Make your Life OS yours.</h2><p className="muted">Connections and preferences stay on this device for now.</p></div><section className="settings-card"><div className="settings-card-head"><div><h3>OpenAI API</h3><p>Configure AI recommendations, Daily Log summaries and Weekly Reviews.</p></div><Icon name="Sparkles" size={20}/></div><label className="settings-label">API key<div className="secret-input"><input type={show?'text':'password'} value={key} onChange={e=>{setKey(e.target.value);setSaved(false)}} placeholder="sk-…" autoComplete="off"/><button type="button" onClick={()=>setShow(!show)}>{show?'Hide':'Show'}</button></div></label><p className="settings-warning"><Icon name="ShieldAlert" size={15}/> This key is saved only in this browser's local storage. Do not use this setup on a public/shared computer. For production AI calls, move the key to a server or Supabase Edge Function.</p><div className="settings-actions"><button className="secondary" onClick={clear} disabled={!key}>Remove key</button><button className="secondary danger-action" onClick={()=>{if(window.confirm('Reset all local progress and return to the starter dataset?')){localStorage.clear();setData(seed);window.location.reload()}}}>Reset app data</button><button className="primary" onClick={save} disabled={!key.trim()}>{saved?'Saved':'Save key'}</button></div></section><CloudSync data={data} setData={setData}/><section className="settings-card"><div className="settings-card-head"><div><h3>App version</h3><p>Current build</p></div><span className="version-chip">v2.5.0</span></div></section><GuideSettingsCard/><ThemePicker/><BackupTools/></div>}
function AIRecommendationsPanel({data}:{data:any}){const[endpoint,setEndpoint]=useState(()=>localStorage.getItem('personal-life-os-ai-endpoint')||'');const[showEndpoint,setShowEndpoint]=useState(false);const[result,setResult]=useState('');const[loading,setLoading]=useState(false);const[message,setMessage]=useState('');const run=async()=>{if(!endpoint.trim()){setMessage('Add your Supabase Edge Function URL first.');return}setLoading(true);setMessage('Generating recommendations…');try{const text=await requestAIRecommendations(endpoint.trim(),{goals:(data.goals||[]).map((g:any)=>g.title),areas:data.areas.map((a:any)=>({name:a.name,focus:a.focus,progress:a.progress})),skills:data.skills.map((s:any)=>({name:s.name,progress:s.progress,practiceCount:s.practiceCount})),tasks:data.tasks.map((t:any)=>({title:t.title,status:t.status,difficulty:t.difficulty})),journal:data.log});setResult(text);setMessage('Updated just now')}catch(error){setMessage(error instanceof Error?error.message:'Unable to generate recommendations')}finally{setLoading(false)}};return <section className="ai-panel"><div className="ai-panel-head"><div><span className="pill purple">AI RECOMMENDATIONS</span><h2>Turn your recent behavior into next steps.</h2><p className="muted">The API Key stays on the Supabase server; this app only sends your growth context.</p></div><Icon name="Sparkles" size={22}/></div><div className="ai-endpoint"><input type={showEndpoint?'text':'password'} value={endpoint} onChange={e=>{setEndpoint(e.target.value);localStorage.setItem('personal-life-os-ai-endpoint',e.target.value)}} placeholder="Supabase Function URL" autoComplete="off"/><button type="button" className="secondary" onClick={()=>setShowEndpoint(!showEndpoint)}>{showEndpoint?'Hide':'Show'}</button><button className="primary" onClick={run} disabled={loading}>{loading?'Working…':'Get recommendations'}</button></div>{message&&<p className="ai-message">{message}</p>}{result&&<div className="ai-result">{result}</div>}</section>}
